// Why Code: free models return JSON as text; parse it, check the fields that decide routing, keep the shape the next nodes expect
if ($json.error) throw new Error('OpenRouter: ' + ($json.error.message ?? JSON.stringify($json.error)));
const msg = $json.choices?.[0]?.message ?? {};
const txt = String(msg.content || msg.reasoning || '');
const m = txt.match(/\{[\s\S]*\}/);
if (!m) throw new Error('Model did not return JSON: ' + txt.slice(0, 200));
let r;
try { r = JSON.parse(m[0]); } catch (e) { throw new Error('Bad JSON from model: ' + e.message); }

// a missing is_enquiry would silently drop a real customer, so stop instead
if (typeof r.is_enquiry !== 'boolean') throw new Error('Model answer has no true/false is_enquiry');
const pick = (v, list, d) => (list.includes(v) ? v : d);
r.category = pick(r.category, ['general', 'service', 'booking', 'support', 'non_enquiry'], r.is_enquiry ? 'general' : 'non_enquiry');
r.travel_type = pick(r.travel_type, ['hotel', 'package', 'tour', 'corporate', 'unknown'], 'unknown');
r.non_enquiry_type = pick(r.non_enquiry_type, ['none', 'spam', 'sales_pitch', 'job_request', 'newsletter', 'notification', 'other'], r.is_enquiry ? 'none' : 'other');
r.needs_reply = typeof r.needs_reply === 'boolean' ? r.needs_reply : r.is_enquiry;
r.is_form_notification = r.is_form_notification === true;
r.summary = typeof r.summary === 'string' ? r.summary : '';
r.customer = r.customer && typeof r.customer === 'object' ? r.customer : {};
r.travel = r.travel && typeof r.travel === 'object' ? r.travel : {};
r.confidence = Number.isFinite(Number(r.confidence)) ? Number(r.confidence) : 0;

return { json: { content: [{ type: 'tool_use', input: r }] } };
